 produce=mission('🌹','Relate o que foi dito','Escreva o que alguém admitiu, negou ou prometeu.','Use admit, deny, insist on ou promise com o padrão certo.','He denied taking the money, but he promised to return it.', [('Usei um verbo de relato?',r'\b(admit|deny|denied|admitted|promis|insist|suggest)\w*\b','denied','Use admit, deny, insist, suggest ou promise.','Verbo: ótimo.'),('Usei -ing?',r'\b(admit|deny|denied|admitted|insist\w*\son)\s\w+ing\b|\b(admit|deny|denied|admitted)\s(\w+\s)?\w+ing\b','denied taking','Use -ing depois de admit ou deny.','Padrão: ótimo.'),('Usei promise to?',r'\bpromis\w*\s(to|that)\b|\bsuggest\w*\sthat\b|\binsist\w*\son\b','promised to','Acrescente promise to, suggest that ou insist on.','Segundo padrão: ótimo.')],['Ótimo: cada verbo tem o padrão certo.','Use um verbo com -ing e outro com to ou that.']),
